sys_script_include.script:
var AttachmentDocumentChecker = Class.create();
AttachmentDocumentChecker.prototype = {
    initialize: function() {},

    // 引数：table名、sys_id、対象キー文字列(例：品名：)、比較先フィールド名
    checkAttachmentFieldMatch: function(table, recordSysId, targetKeyword, targetField) {
        var errorMsg = "";
        // 1. レコード取得
        var grRecord = new GlideRecord(table);
        if(!grRecord.get(recordSysId)) return "対象レコードが存在しません";
        var sheetValue = grRecord.getValue(targetField);

        // 2. 添付ファイル取得
        var grAtt = new GlideRecord("sys_attachment");
        grAtt.addQuery("table_name", table);
        grAtt.addQuery("table_sys_id", recordSysId);
        // PDF/Word/Excelのみ対象
        grAtt.addQuery("content_type", "IN", "application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        grAtt.query();

        if(!grAtt.hasNext()) return "対象の添付ファイル(PDF/Excel/Word)がありません";

        while(grAtt.next()){
            var attSysId = grAtt.sys_id.toString();
            // 3. REST Messageで外部APIにファイル送信、テキスト抽出
            var restMsg = new sn_ws.RESTMessageV2("TextExtractAPI", "postFile");
            restMsg.setStringParameterNoEscape("attachment_sys_id", attSysId);
            var response = restMsg.execute();
            var responseBody = JSON.parse(response.getBody());

            if(response.getStatusCode() !== 200) {
                errorMsg += grAtt.file_name + "：ファイル解析失敗\n";
                continue;
            }
            var fullText = responseBody.text;

            // 4. キーワードから値抽出 例：「品名：xxx」
            var reg = new RegExp(targetKeyword + "\\s*(.+?)[\\n\\r、。,　]", "m");
            var match = fullText.match(reg);
            if(!match || match.length < 2) {
                errorMsg += grAtt.file_name + "：ファイル内に「" + targetKeyword + "」が見つかりません\n";
                continue;
            }
            var fileValue = match[1].trim();

            // 5. 帳票項目と比較
            if(fileValue !== sheetValue) {
                errorMsg += grAtt.file_name + "不一致：ファイル[" + fileValue + "] 帳票[" + sheetValue + "]\n";
            }
        }
        return errorMsg;
    },

    type: "AttachmentDocumentChecker"
};
